import { z } from "zod";

/** Properties that must never be freely edited or generated by AI. */
export const LOCKED_TEMPLATE_PROPERTIES = [
  "canvasWidth",
  "canvasHeight",
  "elementCoordinates",
  "brandColors",
  "fontFamilies",
  "fontWeights",
  "fontSizeRanges",
  "margins",
  "safeZones",
  "logoPosition",
  "logoSize",
  "imageFrames",
  "decorativeElements",
  "slideNumberPosition",
] as const;

export type LockedTemplateProperty = (typeof LOCKED_TEMPLATE_PROPERTIES)[number];

export const FORBIDDEN_USER_CONTROLS = [
  "freeColorPicker",
  "freeFontPicker",
  "freeElementPositioning",
  "freeLayoutGeneration",
  "freeDesignPrompt",
  "unrestrictedTemplateEditing",
] as const;

export const ALLOWED_DYNAMIC_FIELDS = [
  "label",
  "headline",
  "subtitle",
  "body",
  "cta",
  "mainImage",
  "caption",
  "hashtags",
  "altText",
] as const;

/** Content-only fields that may exist in config without appearing in SVG. */
export const NON_VISUAL_DYNAMIC_FIELDS = [
  "caption",
  "hashtags",
  "altText",
] as const;

export const FORMAT_DIMENSIONS = {
  PORTRAIT: { width: 1080, height: 1350, ratio: "4:5" },
  SQUARE: { width: 1080, height: 1080, ratio: "1:1" },
  STORY: { width: 1080, height: 1920, ratio: "9:16" },
} as const;

export const forbiddenControlsSchema = z
  .object(
    Object.fromEntries(
      FORBIDDEN_USER_CONTROLS.map((key) => [key, z.unknown().optional()]),
    ),
  )
  .strict()
  .partial();
